<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const items=ref([]),methods=ref([]),loading=ref(false),saving=ref(false),error=ref(''),modal=ref(false),formError=ref(''),schema=ref(null),schemaError=ref(''),configValues=ref({})
const form=reactive({id:null,name:'',payment:'',icon:'',notify_domain:'',handling_fee_fixed:0,handling_fee_percent:0,config:'{}'})
const paymentOptions=computed(()=>[...new Set([...methods.value,...(form.payment&&!methods.value.includes(form.payment)?[form.payment]:[])])])
function parseConfig(){try{const v=JSON.parse(form.config||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}}
function fieldType(field,key){if(field.type==='number'||field.type==='integer')return 'number';if(field.type==='boolean'||field.type==='switch')return 'checkbox';if(field.type==='password'||/(secret|token|key|password)/i.test(key))return 'password';return 'text'}
async function load(){loading.value=true;error.value='';try{[items.value,methods.value]=await Promise.all([props.api('payment/fetch'),props.api('payment/getPaymentMethods')]);if(!Array.isArray(items.value))items.value=[];if(!Array.isArray(methods.value))methods.value=[]}catch(e){error.value=e.message}finally{loading.value=false}}
function empty(){Object.assign(form,{id:null,name:'',payment:methods.value[0]||'',icon:'',notify_domain:'',handling_fee_fixed:0,handling_fee_percent:0,config:'{}'});schema.value=null;schemaError.value='';configValues.value={};formError.value=''}
async function configForm(){schema.value=null;schemaError.value='';const stored=parseConfig();configValues.value={...stored};try{schema.value=await props.api('payment/getPaymentForm',{method:'POST',body:{payment:form.payment,id:form.id||undefined}});for(const [key,field] of Object.entries(schema.value||{})){if(!Object.prototype.hasOwnProperty.call(configValues.value,key))configValues.value[key]=field.value??''}}catch(e){schemaError.value=e.message+'；仍可通过下方 JSON 编辑已有配置，保存已有支付方式不依赖此表单接口。'}}
function create(){empty();modal.value=true;if(form.payment)configForm()}
function edit(item){empty();Object.assign(form,{id:item.id,name:item.name||'',payment:item.payment||methods.value[0]||'',icon:item.icon||'',notify_domain:item.notify_domain||'',handling_fee_fixed:Number(item.handling_fee_fixed||0),handling_fee_percent:Number(item.handling_fee_percent||0),config:JSON.stringify(item.config||{},null,2)});modal.value=true;configForm()}
async function save(){saving.value=true;formError.value='';try{let config=parseConfig();if(form.config.trim()&&!Object.keys(config).length&&form.config.trim()!=='{}')throw new Error('支付配置必须是有效 JSON 对象。');if(schema.value&&Object.keys(schema.value).length)config={...config,...configValues.value};await props.api('payment/save',{method:'POST',body:{id:form.id||undefined,name:form.name,payment:form.payment,icon:form.icon||null,config,notify_domain:form.notify_domain||null,handling_fee_fixed:Math.round(Number(form.handling_fee_fixed||0)),handling_fee_percent:Number(form.handling_fee_percent||0)}});modal.value=false;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function toggle(item){try{await props.api('payment/show',{method:'POST',body:{id:item.id}});await load()}catch(e){error.value=e.message}}
async function remove(item){if(!window.confirm(`删除支付方式“${item.name}”？已创建订单的支付回调可能受影响。`))return;try{await props.api('payment/drop',{method:'POST',body:{id:item.id}});await load()}catch(e){error.value=e.message}}
async function move(index,delta){const target=index+delta;if(target<0||target>=items.value.length)return;const rows=[...items.value];[rows[index],rows[target]]=[rows[target],rows[index]];try{await props.api('payment/sort',{method:'POST',body:{ids:rows.map(x=>x.id)}});items.value=rows}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="content-view payment-view"><div class="page-title-row"><div><p class="eyebrow">CUSTOMERS / CHECKOUT</p><h1>支付方式<span class="title-period">.</span></h1><p class="page-subtitle">配置支付插件、回调地址与手续费</p></div><button class="assign-order-button" @click="create">＋ 添加支付方式</button></div><div v-if="error" class="api-error"><span>!</span><div><b>支付方式操作失败</b><p>{{error}}</p></div><button @click="load">重试</button></div><div class="users-table-wrap"><div v-if="loading" class="table-state">正在读取支付方式…</div><div v-else-if="!items.length" class="table-state">暂无支付方式。</div><table v-else class="users-table payment-table"><thead><tr><th>名称</th><th>支付插件</th><th>费率</th><th>通知域名</th><th>状态</th><th>排序</th><th>操作</th></tr></thead><tbody><tr v-for="(item,index) in items" :key="item.id"><td><div class="user-cell"><span class="user-initial">￥</span><span><b>{{item.name}}</b><small>ID {{item.id}} · {{item.uuid}}</small></span></div></td><td><code class="trade-code">{{item.payment}}</code></td><td>{{item.handling_fee_fixed||0}} 分 + {{item.handling_fee_percent||0}}%</td><td>{{item.notify_domain||'使用站点地址'}}</td><td><button class="user-status status-button" :class="{disabled:!item.enable}" @click="toggle(item)">{{item.enable?'已启用':'已停用'}}</button></td><td><div class="sort-actions"><button :disabled="index===0" @click="move(index,-1)">↑</button><button :disabled="index===items.length-1" @click="move(index,1)">↓</button></div></td><td><div class="row-actions"><button @click="edit(item)">编辑</button><button class="danger-action" @click="remove(item)">删除</button></div></td></tr></tbody></table></div><div class="footer-note"><span>XB CONTROL ROOM</span><span>支付方式配置包含密钥，请仅在可信设备上操作</span></div>
<div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="user-modal payment-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">CHECKOUT / {{form.id?'EDIT':'CREATE'}}</p><h2>{{form.id?'编辑支付方式':'添加支付方式'}}</h2></div><button class="modal-close" @click="modal=false">×</button></header><form class="user-form" @submit.prevent="save"><label>显示名称<input v-model.trim="form.name" required /></label><label>支付插件<select v-model="form.payment" required @change="configForm"><option v-for="method in paymentOptions" :key="method" :value="method">{{method}}{{!methods.includes(method)?'（当前配置不可用）':''}}</option></select></label><div class="schema-card"><div class="schema-head"><b>插件配置字段</b><button type="button" @click="configForm">读取字段定义</button></div><pre>{{schema===null?'选择插件以读取配置定义。':JSON.stringify(schema,null,2)}}</pre></div><p v-if="schemaError" class="notice">{{schemaError}}</p><template v-if="schema&&Object.keys(schema).length"><label v-for="(field,key) in schema" :key="key">{{field.label||key}}<small v-if="field.description" class="field-hint">{{field.description}}</small><select v-if="field.options&&Object.keys(field.options).length" v-model="configValues[key]"><option v-for="(label,value) in field.options" :key="value" :value="value">{{label}}</option></select><textarea v-else-if="field.type==='textarea'" v-model="configValues[key]" rows="4"></textarea><input v-else v-model="configValues[key]" :type="fieldType(field,key)" :step="fieldType(field,key)==='number'?'any':undefined" :required="field.required" :placeholder="field.placeholder||''"/></label></template><details><summary>{{schema&&Object.keys(schema).length?'高级配置 JSON':'配置 JSON（表单接口不可用时编辑此项）'}}</summary><label>配置 JSON<textarea v-model="form.config" rows="8" spellcheck="false" required></textarea></label></details><div class="form-pair"><label>固定手续费（分）<input v-model.number="form.handling_fee_fixed" type="number" min="0" /></label><label>百分比手续费（%）<input v-model.number="form.handling_fee_percent" type="number" min="0" max="100" step="0.01" /></label></div><label>自定义通知域名（可选）<input v-model.trim="form.notify_domain" type="url" placeholder="https://pay.example.com" /></label><label>图标标识（可选）<input v-model.trim="form.icon" /></label><p v-if="formError" class="notice">{{formError}}</p><footer class="modal-footer"><button type="button" class="cancel-button" @click="modal=false">取消</button><button type="submit" class="save-button" :disabled="saving">{{saving?'保存中…':'保存支付方式'}}</button></footer></form></section></div></section></template>
